const { chromium } = require('D:/repository/家园区一网通办/node_modules/@playwright/test');
(async () => {
  const browser = await chromium.launch({ executablePath: 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe' });
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true });
  const page = await context.newPage();
  // 用多选项较多的题模拟内容较长
  const goHandleResp = { MtplQuestionnaireModel: { description: '苏州工业园区业主（使用人）2025年度满意度抽样调查', totalCount: 2784, joinedCount: 7, examsList: [
    { type: 4, topic: '您对本小区物业管理服务的期望如何？', hint: '最低半颗星，满分5星', nochoisenum: 1, nochoisenumPJ: '' },
    { type: 0, topic: '第二题：单选题（多选项，测试是否能看到最后一个选项）', options: ['选项A','选项B','选项C','选项D','选项E','选项F','选项G','选项H'], nochoisenum: 1 },
  ] } };
  await context.route('**/*SmQuestionnaireGoHandleApp*', r => r.fulfill({ status:200, contentType:'application/json', body: JSON.stringify(goHandleResp) }));
  await context.route('**/*SmQuestionnaireReplyRate*', r => r.fulfill({ status:200, contentType:'application/json', body: JSON.stringify({rate:'0.25',totalHouse:2784,replyHouse:7}) }));
  await page.addInitScript((s)=>localStorage.setItem('survey', JSON.stringify(s)), { tableId:'T1',roomNo:'R1',projectCode:'P1',projectName:'香堤澜湾花园',title:'民意调查',ECode:'E1' });
  await page.goto('http://localhost:8092/wechatapph5/#/pages-survey/index', { waitUntil:'networkidle', timeout:30000 });
  await page.waitForTimeout(2000);

  // 跳到第2题（多选项）看底部遮挡
  const rate = await page.$('.survey-rate-wrapper'); const box = await rate.boundingBox();
  await page.mouse.click(box.x + box.width*0.5, box.y + box.height/2); await page.waitForTimeout(300);
  const nextBtns = await page.$$('.survey-page-text-btn');
  for (const b of nextBtns){ const t=(await b.innerText()).trim(); if(t.includes('下一题')){ await b.click(); break; } }
  await page.waitForTimeout(600);

  const info = await page.evaluate(() => {
    const footer = document.querySelector('.survey-page-footer');
    const content = document.querySelector('.survey-page-content');
    const scroll = document.querySelector('.survey-page-answer-scrollable');
    const options = Array.from(document.querySelectorAll('.survey-page-options .survey-page-option, .survey-page-options > div'));
    const lastOption = options[options.length-1];
    const f = footer.getBoundingClientRect();
    const c = content.getBoundingClientRect();
    const s = scroll.getBoundingClientRect();
    const lo = lastOption ? lastOption.getBoundingClientRect() : null;
    return {
      viewportH: window.innerHeight,
      footerTop: f.top, footerHeight: f.height, footerBottom: f.bottom,
      contentTop: c.top, contentBottom: c.bottom, contentHeight: c.height,
      scrollTop: s.top, scrollBottom: s.bottom, scrollScrollHeight: scroll.scrollHeight, scrollClientHeight: scroll.clientHeight,
      lastOptionTop: lo && lo.top, lastOptionBottom: lo && lo.bottom,
      lastOptionHiddenByFooter: lo ? (lo.bottom > f.top) : null,
      optionCount: options.length,
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await page.screenshot({ path: 'D:\\tmp\\overlap_q2.png' });
  await browser.close();
})().catch(e=>{console.error('FATAL',e);process.exit(1)});

